/**
 * The Subless mark, inlined as base64.
 *
 * Icon and Open Graph routes render with `next/og`, which needs the image as
 * data rather than a path. Reading from `public/` at runtime is not reliable on
 * a serverless deploy — those files are not guaranteed to be traced into the
 * function bundle — so the bytes live in source, where nothing can lose them.
 *
 * 256px is well above what any icon slot needs and keeps this under 60KB.
 */
export const SWAN_DATA_URI =
  "data:image/png;base64,";
